export class Vec {
    x;
    y;
    constructor(x, y) {
        this.x = x;
        this.y = y;
    }
    get l() {
        return [this.x, this.y];
    }
    // ベクトル
    add(v) {
        return new Vec(this.x + v.x, this.y + v.y);
    }
    sub(v) {
        return new Vec(this.x - v.x, this.y - v.y);
    }
    scale(s) {
        return new Vec(this.x * s, this.y * s);
    }
    clone() {
        return new Vec(this.x, this.y);
    }
    normalize() {
        const l = this.magnitude();
        return l === 0 ? new Vec(0, 0) : new Vec(this.x / l, this.y / l);
    }
    // 反時計回り(数学的な正方向)に rad 回転させる
    rotate(rad) {
        const c = Math.cos(rad);
        const s = Math.sin(rad);
        return new Vec(this.x * c - this.y * s, this.x * s + this.y * c);
    }
    // 元進行方向を反時計回りに90度回した法線
    normal() {
        const n = this.normalize();
        return new Vec(n.y, -n.x);
    }
    // ここからスカラー
    magnitude() {
        return Math.hypot(this.x, this.y);
    }
    magnitudeSquared() {
        return this.x ** 2 + this.y ** 2;
    }
    dot(v) {
        return this.x * v.x + this.y * v.y;
    }
    // 外積 (this × v)
    cross(v) {
        return this.x * v.y - this.y * v.x;
    }
    radian() {
        return Math.atan2(this.y, this.x);
    }
}
export const vec = (x, y) => new Vec(x, y);
vec.arg = (radian) => new Vec(Math.cos(radian), Math.sin(radian));
